{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "district",
      "as": "agg1",
      "group_by": [],
      "metrics": [
        {
          "as": "avg_1995",
          "fn": "mean",
          "column": "A12"
        },
        {
          "as": "avg_1996",
          "fn": "mean",
          "column": "A13"
        }
      ]
    },
    {
      "op": "derive",
      "input": "agg1",
      "as": "result",
      "column": "higher_year",
      "expr": "('1995' if avg_1995 > avg_1996 else ('1996' if avg_1996 > avg_1995 else 'equal'))"
    },
    {
      "op": "select",
      "input": "result",
      "as": "final",
      "columns": ["avg_1995", "avg_1996", "higher_year"]
    }
  ]
}

