{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "superhero",
      "as": "filtered",
      "where": "height_cm >= 150 and height_cm <= 180"
    },
    {
      "op": "derive",
      "input": "filtered",
      "as": "with_flag",
      "column": "is_marvel",
      "expr": "1 if publisher_id == 13 else 0"
    },
    {
      "op": "aggregate",
      "input": "with_flag",
      "as": "agg",
      "group_by": [],
      "metrics": [
        {
          "as": "total",
          "fn": "count",
          "column": "id"
        },
        {
          "as": "marvel",
          "fn": "sum",
          "column": "is_marvel"
        }
      ]
    },
    {
      "op": "derive",
      "input": "agg",
      "as": "with_percentage",
      "column": "percentage",
      "expr": "marvel / total * 100"
    },
    {
      "op": "select",
      "input": "with_percentage",
      "as": "result",
      "columns": ["percentage"]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "join",
      "input": "superhero",
      "as": "sh_pub",
      "right": "publisher",
      "left_on": ["publisher_id"],
      "right_on": ["id"],
      "how": "inner"
    },
    {
      "op": "derive",
      "input": "sh_pub",
      "as": "with_flags",
      "column": "is_dc",
      "expr": "publisher_name == 'DC Comics'"
    },
    {
      "op": "derive",
      "input": "with_flags",
      "as": "with_flags2",
      "column": "is_marvel",
      "expr": "publisher_name == 'Marvel Comics'"
    },
    {
      "op": "aggregate",
      "input": "with_flags2",
      "as": "counts",
      "group_by": [],
      "metrics": [
        {
          "as": "dc_count",
          "fn": "sum",
          "column": "is_dc"
        },
        {
          "as": "marvel_count",
          "fn": "sum",
          "column": "is_marvel"
        }
      ]
    },
    {
      "op": "derive",
      "input": "counts",
      "as": "diff_calc",
      "column": "difference",
      "expr": "dc_count - marvel_count"
    },
    {
      "op": "derive",
      "input": "diff_calc",
      "as": "result",
      "column": "more_publisher",
      "expr": "('DC Comics' if difference > 0 else ('Marvel Comics' if difference < 0 else 'Tie'))"
    },
    {
      "op": "select",
      "input": "result",
      "as": "final",
      "columns": ["more_publisher", "difference"]
    }
  ]
}

{
  "status": "plan",
